queries.query:
import "math"

// Define the time range and filter for Az data
data = from(bucket: "efd/autogen")
  |> range(start: dashboardTime, stop: upperDashboardTime)
  |> filter(fn: (r) => r._measurement == "lsst.sal.MTPtg.mountStatus" and r._field == "mountAz")
  |> last()  // Retrieve only the last data point

// Function to convert Az from decimal degrees to DD:MM:SS.S format
formatAz = (az) => {
  sign = if az < 0.0 then "-" else "+"  // Handle the sign first
  az_abs = math.abs(x: az)  // Take the absolute value of azimuth for further processing

  degs = int(v: az_abs)  // Get the integer degree part
  minutes_decimal = (az_abs - float(v: degs)) * 60.0  // Get the decimal part for minutes
  minutes = int(v: minutes_decimal)  // Get the integer minute part
  seconds = (minutes_decimal - float(v: minutes)) * 60.0  // Get the seconds
  seconds_str = string(v: math.round(x: seconds * 10.0) / 10.0)  // Round seconds to 1 decimal place

  // Return azimuth in D:M:S format with appropriate sign
  return sign + string(v: degs) + "°" + string(v: minutes) + "'" + seconds_str + "\""
}

//formatAz = (az) => {
//  degs = int(v: az)
//  minutes_decimal = (az - float(v: degs)) * 60.0
//  minutes = int(v: minutes_decimal)
//  seconds = (minutes_decimal - float(v: minutes)) * 60.0
//  seconds_str = string(v: math.round(x: seconds * 10.0) / 10.0)
//  return string(v: degs) + "°" + string(v: minutes) + "'" + seconds_str + "\""
//}

// Map over the data to include raw and formatted Az
data
  |> map(fn: (r) => ({
    _time: r._time,
    raw_Az_degrees: r._value,  // Raw Az in degrees
    formatted_Az: formatAz(az: float(v: r._value / 1.0))  // Az is already in degrees
  }))
  |> yield(name: "Last_Az")

